/* ------------------------------------------------------------------ small helpers */

static int clampi(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }
static float clampf(float v, float lo, float hi) { return v < lo ? lo : (v > hi ? hi : v); }
static int imin(int a, int b) { return a < b ? a : b; }
static int imax(int a, int b) { return a > b ? a : b; }
static float fminf2(float a, float b) { return a < b ? a : b; }
static float fmaxf2(float a, float b) { return a > b ? a : b; }
static int ifloor(float v) { return (int)floorf(v); }

static uint32_t rng_state = 2463534242u;
static uint32_t rng_next(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}
static float frand(void) { return (rng_next() & 0xFFFFFF) / 16777216.0f; }
static int irand(int n) { return (int)(rng_next() % (uint32_t)n); }

/* ------------------------------------------------------------------ blocks & items */

static const char *block_name[BLOCK_COUNT];
static int tile_top[BLOCK_COUNT], tile_side[BLOCK_COUNT], tile_bottom[BLOCK_COUNT];
static float block_hard[BLOCK_COUNT];
static int block_solid[BLOCK_COUNT], block_glow[BLOCK_COUNT], block_rock[BLOCK_COUNT];

static void def_block(int id, const char *n, int top, int side, int bottom, float h, int solid, int glow, int rock) {
    block_name[id] = n;
    tile_top[id] = top;
    tile_side[id] = side;
    tile_bottom[id] = bottom;
    block_hard[id] = h;
    block_solid[id] = solid;
    block_glow[id] = glow;
    block_rock[id] = rock;
}

