    def_block(GOLD_ORE, "Gold Ore", 17, 17, 17, 5.5f, 1, 0, 1);
    def_block(DIAMOND_ORE, "Diamond Ore", 18, 18, 18, 7.0f, 1, 0, 1);
    def_block(BRICKS, "Bricks", 19, 19, 19, 4.0f, 1, 0, 1);
    def_block(BEDROCK, "Bedrock", 20, 20, 20, -1.0f, 1, 0, 0);
