static void con_print(const char *fmt, ...) {
    char buf[160];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    if (con_n == LOG_LINES) {
        memmove(con_log[0], con_log[1], sizeof(con_log[0]) * (LOG_LINES - 1));
        con_n--;
    }
    snprintf(con_log[con_n++], sizeof con_log[0], "%s", buf);
}
static void set_banner(const char *s) { snprintf(banner, sizeof banner, "%s", s); banner_t = 3.0f; }

static float brightness_of(float t) { return clampf(sinf(t * TAU_F) * 1.5f + 0.75f, 0.14f, 1.0f); }

/* ---- inventory ---- */
static void inv_give(int id, int n) {
    g_inv[id] += n;
    if (g_mode == 1) {
        int has = 0, empty = -1;
        for (int i = 0; i < 9; i++) {
            if (g_hotbar[i] == id) has = 1;
            if (g_hotbar[i] == 0 && empty < 0) empty = i;
        }
        if (!has && empty >= 0) g_hotbar[empty] = id;
    }
}
static int inv_take(int id, int n) {
    if (g_inv[id] < n) return 0;
    g_inv[id] -= n;
    return 1;
}
static float best_pick(void) {
    float best = 1.0f;
    for (int p = IT_WOOD_PICK; p <= IT_DIAMOND_PICK; p++) if (g_inv[p] > 0) best = fmaxf2(best, pick_power(p));
    return best;
}

typedef struct { int out, outc, npairs, need[6]; } Recipe;
static const Recipe recipes[] = {
    {PLANKS, 4, 1, {LOG, 1}}, {PLANKS, 4, 1, {SPRUCE_LOG, 1}}, {IT_STICK, 4, 1, {PLANKS, 2}},
    {IT_WOOD_PICK, 1, 2, {PLANKS, 3, IT_STICK, 2}}, {IT_STONE_PICK, 1, 2, {COBBLE, 3, IT_STICK, 2}},
    {IT_IRON_PICK, 1, 2, {IT_IRON, 3, IT_STICK, 2}}, {IT_DIAMOND_PICK, 1, 2, {IT_DIAMOND, 3, IT_STICK, 2}},
    {STONE, 1, 2, {COBBLE, 1, IT_COAL, 1}}, {BRICKS, 4, 1, {STONE, 4}}, {BED, 1, 2, {PLANKS, 3, LEAVES, 2}},
    {LUMEN, 1, 2, {IT_GOLD, 1, IT_COAL, 1}}, {PORTAL, 1, 2, {IT_DIAMOND, 1, COBBLE, 4}},
    {VOIDGATE, 1, 2, {IT_DIAMOND, 2, IT_GOLD, 1}}
};
#define N_RECIPES ((int)(sizeof(recipes) / sizeof(recipes[0])))
static const Recipe trades[] = {
    {IT_APPLE, 2, 1, {IT_COAL, 3}}, {IT_GOLD, 1, 1, {IT_IRON, 2}}, {BED, 1, 1, {IT_GOLD, 1}},
    {IT_DIAMOND, 1, 1, {IT_GOLD, 2}}, {VOIDGATE, 1, 2, {IT_DIAMOND, 1, IT_MEAT, 2}}
};
#define N_TRADES ((int)(sizeof(trades) / sizeof(trades[0])))

static int can_craft(const Recipe *r) {
    for (int i = 0; i < r->npairs; i++) if (g_inv[r->need[i * 2]] < r->need[i * 2 + 1]) return 0;
    return 1;
}
static int do_craft(const Recipe *r) {
    if (!can_craft(r)) return 0;
    for (int i = 0; i < r->npairs; i++) inv_take(r->need[i * 2], r->need[i * 2 + 1]);
    inv_give(r->out, r->outc);
    return 1;
}
static void describe_recipe(const Recipe *r, char *out, size_t n) {
    out[0] = 0;
    for (int i = 0; i < r->npairs; i++) {
        char t[64];
        snprintf(t, sizeof t, "%s%d %s", i ? ", " : "", r->need[i * 2 + 1], item_name(r->need[i * 2]));
        strncat(out, t, n - strlen(out) - 1);
    }
}

/* ---- dirty chunks ---- */
static void dirty_at(int cx, int cz) {
    Chunk *c = world_chunk(cw, cx, cz);
    if (c) c->dirty = 1;
}
static void mark_dirty(int x, int z) {
    int cx = x >> 4, cz = z >> 4;
    dirty_at(cx, cz);
    if ((x & 15) == 0) dirty_at(cx - 1, cz);
    if ((x & 15) == 15) dirty_at(cx + 1, cz);
    if ((z & 15) == 0) dirty_at(cx, cz - 1);
    if ((z & 15) == 15) dirty_at(cx, cz + 1);
}

/* ---- chunk streaming ---- */
#define MAX_RING 600
static int ring_dx[MAX_RING], ring_dz[MAX_RING], ring_n;
static void build_ring(void) {
    int r = 12;
    ring_n = 0;
    for (int dx = -r; dx <= r; dx++) for (int dz = -r; dz <= r; dz++) {
        if (dx * dx + dz * dz <= r * r && ring_n < MAX_RING) { ring_dx[ring_n] = dx; ring_dz[ring_n] = dz; ring_n++; }
    }
    for (int i = 1; i < ring_n; i++) { /* insertion sort by distance */
        int ax = ring_dx[i], az = ring_dz[i], d = ax * ax + az * az, j = i - 1;
        while (j >= 0 && ring_dx[j] * ring_dx[j] + ring_dz[j] * ring_dz[j] > d) {
            ring_dx[j + 1] = ring_dx[j]; ring_dz[j + 1] = ring_dz[j]; j--;
        }
        ring_dx[j + 1] = ax; ring_dz[j + 1] = az;
    }
}
static int has_neighbors(Chunk *c) {
    return world_chunk(cw, c->cx + 1, c->cz) && world_chunk(cw, c->cx - 1, c->cz) &&
           world_chunk(cw, c->cx, c->cz + 1) && world_chunk(cw, c->cx, c->cz - 1);
}
static void stream_chunks(int gen_budget, int mesh_budget) {
    static int frame = 0;
    int pcx = ifloor(px) >> 4, pcz = ifloor(pz) >> 4;
    int gen_r = set_dist + 1;
    for (int i = 0; i < ring_n && gen_budget > 0; i++) {
        if (ring_dx[i] * ring_dx[i] + ring_dz[i] * ring_dz[i] > gen_r * gen_r) break;
        if (!world_chunk(cw, pcx + ring_dx[i], pcz + ring_dz[i])) { world_ensure(cw, pcx + ring_dx[i], pcz + ring_dz[i]); gen_budget--; }
    }
    for (int i = 0; i < ring_n && mesh_budget > 0; i++) {
        if (ring_dx[i] * ring_dx[i] + ring_dz[i] * ring_dz[i] > set_dist * set_dist) break;
        Chunk *c = world_chunk(cw, pcx + ring_dx[i], pcz + ring_dz[i]);
        if (!c || !c->dirty || !has_neighbors(c)) continue;
        mesh_chunk(cw, c);
        mesh_budget--;
    }
    if (++frame % 45 == 0) { /* forget far chunks (their edits are kept) */
        for (int b = 0; b < CH_HASH; b++) {
            Chunk *c = cw->buckets[b];
            while (c) {
                Chunk *n = c->next;
                int dx = c->cx - pcx, dz = c->cz - pcz;
                if (dx * dx + dz * dz > (gen_r + 2) * (gen_r + 2)) { free_chunk_gl(c); world_remove(cw, c); }
                c = n;
            }
        }
    }
}
static void release_world(World *w) {
    for (int b = 0; b < CH_HASH; b++) {
        Chunk *c = w->buckets[b];
        while (c) { Chunk *n = c->next; free_chunk_gl(c); free(c); c = n; }
        w->buckets[b] = NULL;
    }
    w->nchunks = 0;
    w->cache = NULL;
}
static void free_edits(World *w) {
    for (int b = 0; b < CE_HASH; b++) {
        CE *e = w->ce[b];
        while (e) { CE *n = e->next; free(e->idx); free(e->b); free(e); e = n; }
        w->ce[b] = NULL;
    }
}

/* ---- dimensions ---- */
static int find_nether_spot(World *w, int x, int z) {
    for (int y = 40; y >= 15; y--) {
        if (world_solid(w, x, y - 1, z) && !world_solid(w, x, y, z) && !world_solid(w, x, y + 1, z) &&
            world_get(w, x, y, z) != LAVA && world_get(w, x, y + 1, z) != LAVA) return y;
    }
    for (int dx = -2; dx <= 2; dx++) for (int dz = -2; dz <= 2; dz++) {
        world_set(w, x + dx, 31, z + dz, EMBER);
        for (int dy = 0; dy <= 3; dy++) world_set(w, x + dx, 32 + dy, z + dz, AIR);
    }
    return 32;
}

static void switch_dim(int nd, int tx, int tz, int gate_kind) {
    World *w = &worlds[nd];
    for (int dx = -1; dx <= 1; dx++) for (int dz = -1; dz <= 1; dz++) world_ensure(w, (tx >> 4) + dx, (tz >> 4) + dz);
    int sy = nd == 1 ? find_nether_spot(w, tx, tz) : world_surface_y(w, tx, tz) + 1;
    if (gate_kind) {
        int gx = tx + 2, gy = sy - 1;
        world_set(w, gx, gy, tz, gate_kind);
        world_set(w, gx, gy + 1, tz, AIR);
        world_set(w, gx, gy + 2, tz, AIR);
        if (!world_solid(w, gx, gy - 1, tz)) world_set(w, gx, gy - 1, tz, nd == 1 ? EMBER : (nd == 2 ? END_STONE : STONE));
    }
    if (w != cw) release_world(cw);
    cw = w;
    nmobs = 0;
    g_dim = nd;
    px = tx + 0.5f; pz = tz + 0.5f; py = (float)sy;
    vx = vy = vz = 0.0f;
    portal_t = 0.0f; was_air = 0; fall_top = py; hit = 0;
    cur_biome[0] = 0;
}

static void goto_dim(int nd, int kind) {
    int tx = ifloor(px), tz = ifloor(pz);
    if (nd == 2) { end_ret_dim = g_dim; end_ret_x = tx; end_ret_z = tz; tx = 0; tz = 0; }
    else if (g_dim == 2) { tx = end_ret_x; tz = end_ret_z; }
    switch_dim(nd, tx, tz, kind);
}

static void damage(int n);
static void respawn(void) {
    set_banner("You died");
    g_health = 20;
    g_flying = 0;
    if (g_has_spawn) {
        int sx = ifloor(g_sx), sz = ifloor(g_sz);
        if (g_dim != 0) switch_dim(0, sx, sz, 0); else world_ensure(cw, sx >> 4, sz >> 4);
        px = g_sx; pz = g_sz; py = g_sy;
        if (!world_solid(cw, sx, ifloor(py) - 1, sz)) py = world_surface_y(cw, sx, sz) + 1.0f;
    } else if (g_dim != 0) {
        switch_dim(0, 8, 8, 0);
    } else {
        world_ensure(cw, 0, 0);
        px = 8.5f; pz = 8.5f; py = world_surface_y(cw, 8, 8) + 1.0f;
    }
    nmobs = 0;
    vx = vy = vz = 0.0f;
    fall_top = py;
    was_air = 0;
}
static void damage(int n) {
    g_health = imax(0, g_health - n);
    if (g_health <= 0) respawn();
}

/* ---- mobs ---- */
static Mob *add_mob(int type, float x, float y, float z) {
    if (nmobs >= MAX_MOBS) return NULL;
    Mob *m = &mobs[nmobs++];
    memset(m, 0, sizeof *m);
    m->type = type; m->x = x; m->y = y; m->z = z; m->hp = mob_hp0[type]; m->homex = x; m->homez = z;
    return m;
}

static int find_spawn_y(int x, int z, int near_y) {
    if (!world_chunk(cw, x >> 4, z >> 4)) return -1;
    int y = imin(WH - 3, near_y + 10), lo = imax(2, near_y - 24);
    for (; y >= lo; y--) {
        if (world_solid(cw, x, y - 1, z) && !world_solid(cw, x, y, z) && !world_solid(cw, x, y + 1, z) &&
            world_get(cw, x, y, z) != LAVA && world_get(cw, x, y - 1, z) != LAVA) return y;
    }
    return -1;
}

static int mob_collides(const Mob *m, float x, float y, float z) {
    float hw = mob_hw[m->type], h = mob_h[m->type];
    int x0 = ifloor(x - hw), x1 = ifloor(x + hw), y0 = ifloor(y), y1 = ifloor(y + h), z0 = ifloor(z - hw), z1 = ifloor(z + hw);
    for (int xx = x0; xx <= x1; xx++) for (int yy = y0; yy <= y1; yy++) for (int zz = z0; zz <= z1; zz++)
        if (world_solid(cw, xx, yy, zz)) return 1;
    return 0;
}

static void spawn_mobs(float dt) {
    spawn_t -= dt;
    if (spawn_t > 0.0f) return;
    spawn_t = 1.5f;
    int hostile = 0, passive = 0, villagers = 0;
    for (int i = 0; i < nmobs; i++) {
        if (mob_hostile(mobs[i].type)) hostile++;
        else if (mobs[i].type == MOB_VILLAGER) villagers++;
        else passive++;
    }
    float bright = brightness_of(g_time);
    if (g_dim == 0) {
        Village v;
        if (village_in_region(cw, ifloor(px) >> 7, ifloor(pz) >> 7, &v)) {
            float ddx = v.cx - px, ddz = v.cz - pz;
            if (ddx * ddx + ddz * ddz < 3600.0f && villagers < 4) {
                int x = v.cx + irand(13) - 6, z = v.cz + irand(13) - 6;
                int y = find_spawn_y(x, z, v.h + 1);
                if (y >= 0) {
                    Mob *m = add_mob(MOB_VILLAGER, x + 0.5f, (float)y, z + 0.5f);
                    if (m) { m->homex = v.cx + 0.5f; m->homez = v.cz + 0.5f; }
                }
            }
        }
    }
    float ang = frand() * TAU_F, r = 14.0f + frand() * 12.0f;
    int x = ifloor(px + sinf(ang) * r), z = ifloor(pz + cosf(ang) * r);
    int y = find_spawn_y(x, z, ifloor(py));
    if (y < 0) return;
    float fx = x + 0.5f, fz = z + 0.5f;
    if (g_dim == 0) {
        if (bright < 0.3f && hostile < 7) add_mob(MOB_SHADE, fx, (float)y, fz);
        else if (bright > 0.45f && passive < 10) {
            int below = world_get(cw, x, y - 1, z);
            if (below == GRASS || below == SNOWY_GRASS) add_mob(irand(2) ? MOB_BOAR : MOB_COW, fx, (float)y, fz);
        }
    } else if (g_dim == 1) {
        if (hostile < 6) add_mob(MOB_CINDER, fx, (float)y, fz);
    } else if (hostile < 4) add_mob(MOB_VOIDLING, fx, (float)y, fz);
}

static void update_mobs(float dt) {
    float bright = brightness_of(g_time);
    int daylight = g_dim == 0 && bright > 0.6f;
    int i = 0;
    while (i < nmobs) {
        Mob *m = &mobs[i];
        float dx = px - m->x, dz = pz - m->z, dist = sqrtf(dx * dx + dz * dz);
        if (dist > 72.0f || m->y < -12.0f || m->hp <= 0.0f) { mobs[i] = mobs[--nmobs]; continue; }
        m->atk_cd -= dt; m->hurt -= dt;
        if (daylight && m->type == MOB_SHADE) { m->burn += dt; if (m->burn >= 1.0f) { m->burn -= 1.0f; m->hp -= 2.0f; } }
        int hostile = mob_hostile(m->type), moving = 0;
        float speed = mob_speed[m->type], wx = 0.0f, wz = 0.0f;
        if (hostile && dist < 20.0f && g_health > 0) {
            m->yaw = atan2f(dx, dz);
            if (dist > 1.2f) { wx = sinf(m->yaw); wz = cosf(m->yaw); moving = 1; }
            if (dist < 1.7f && fabsf(py - m->y) < 1.6f && m->atk_cd <= 0.0f) {
                m->atk_cd = 1.0f;
                if (g_mode == 1) damage(mob_dmg[m->type]);
            }
        } else {
            m->timer -= dt;
            if (m->timer <= 0.0f) {
                m->timer = 2.0f + frand() * 4.0f;
                m->walking = irand(3) != 0;
                m->yaw = frand() * TAU_F;
                if (m->type == MOB_VILLAGER) {
                    float hx2 = m->homex - m->x, hz2 = m->homez - m->z;
                    if (hx2 * hx2 + hz2 * hz2 > 100.0f) { m->yaw = atan2f(hx2, hz2); m->walking = 1; }
                }
            }
            if (m->hurt > 0.0f && !hostile) { m->yaw = atan2f(-dx, -dz); speed *= 2.0f; m->walking = 1; }
            if (m->walking) { wx = sinf(m->yaw); wz = cosf(m->yaw); moving = 1; }
        }
        int in_lava = world_get(cw, ifloor(m->x), ifloor(m->y + 0.3f), ifloor(m->z)) == LAVA;
        int burning = in_lava && m->type != MOB_CINDER;
        m->vy = burning ? 2.0f : fmaxf2(m->vy - 26.0f * dt, -30.0f);
        if (burning) m->hp -= dt * 4.0f;
        float nx = m->x + (wx * speed + m->kx) * dt;
        int blocked = 0;
        if (!mob_collides(m, nx, m->y, m->z)) m->x = nx; else blocked = 1;
        float nz = m->z + (wz * speed + m->kz) * dt;
        if (!mob_collides(m, m->x, m->y, nz)) m->z = nz; else blocked = 1;
        float ny = m->y + m->vy * dt;
        m->on_ground = 0;
        if (!mob_collides(m, m->x, ny, m->z)) m->y = ny;
        else { if (m->vy < 0.0f) m->on_ground = 1; m->vy = 0.0f; }
        if (blocked && m->on_ground && moving) m->vy = 7.5f;
        float decay = fmaxf2(0.0f, 1.0f - 6.0f * dt);
        m->kx *= decay; m->kz *= decay;
        if (moving) m->phase += dt * 9.0f;
        i++;
    }
}

static Mob *target_mob(float reach) {
    if (!nmobs) return NULL;
    float oy = py + 1.62f;
    float dx = sinf(yaw) * cosf(pitch), dy = sinf(pitch), dz = -cosf(yaw) * cosf(pitch);
    for (float t = 0.0f; t < reach; t += 0.1f) {
        float x = px + dx * t, y = oy + dy * t, z = pz + dz * t;
        if (world_get(cw, ifloor(x), ifloor(y), ifloor(z)) != AIR) return NULL;
        for (int i = 0; i < nmobs; i++) {
            Mob *m = &mobs[i];
            float hw = mob_hw[m->type] + 0.1f;
            if (fabsf(x - m->x) <= hw && fabsf(z - m->z) <= hw && y >= m->y && y <= m->y + mob_h[m->type]) return m;
        }
    }
    return NULL;
}

static void hit_mob(Mob *m) {
    float dmg = g_mode == 0 ? 20.0f : 2.0f + best_pick() * 0.5f;
    m->hp -= dmg; m->hurt = 0.35f; swing_t = 1.0f;
    float dx = m->x - px, dz = m->z - pz, d = sqrtf(dx * dx + dz * dz) + 0.001f;
    m->kx = dx / d * 6.0f; m->kz = dz / d * 6.0f; m->vy = 5.0f;
    if (m->hp <= 0.0f && !m->dead) {
        m->dead = 1;
        if (g_mode == 1) {
            switch (m->type) {
                case MOB_BOAR: case MOB_COW: inv_give(IT_MEAT, 1 + irand(2)); break;
                case MOB_SHADE: if (irand(2)) inv_give(IT_COAL, 1); break;
                case MOB_CINDER: if (irand(3) == 0) inv_give(IT_GOLD, 1); break;
                case MOB_VOIDLING: if (irand(4) == 0) inv_give(IT_DIAMOND, 1); break;
                default: break;
            }
        }
    }
}

static void do_sleep(void) {
    if (g_dim != 0) { set_banner("You can only sleep in the Overworld"); return; }
    if (brightness_of(g_time) < 0.45f || g_mode == 0) {
        g_time = 0.02f; g_has_spawn = 1; g_sx = hx + 0.5f; g_sy = hy + 1.0f; g_sz = hz + 0.5f; g_health = 20;
        for (int i = 0; i < nmobs;) { if (mob_hostile(mobs[i].type)) mobs[i] = mobs[--nmobs]; else i++; }
        set_banner("Good morning! Spawn point set");
    } else set_banner("You can only sleep at night");
}

/* ---- commands (the "/" console) ---- */
static void lower(char *s) { for (; *s; s++) if (*s >= 'A' && *s <= 'Z') *s = (char)(*s + 32); }
static void norm_name(const char *src, char *dst, size_t n) {
    size_t k = 0;
    for (; *src && k + 1 < n; src++) {
        char ch = *src;
        if (ch == ' ' || ch == '_' || ch == '-') continue;
        if (ch >= 'A' && ch <= 'Z') ch = (char)(ch + 32);
        dst[k++] = ch;
    }
    dst[k] = 0;
}
static void teleport_to(float x, int has_y, float y, float z) {
    int ix = ifloor(x), iz = ifloor(z);
    for (int dx = -1; dx <= 1; dx++) for (int dz = -1; dz <= 1; dz++) world_ensure(cw, (ix >> 4) + dx, (iz >> 4) + dz);
    px = x; pz = z;
    py = has_y ? y : (g_dim == 1 ? (float)find_nether_spot(cw, ix, iz) : world_surface_y(cw, ix, iz) + 1.0f);
    vx = vy = vz = 0.0f; fall_top = py; was_air = 0;
    con_print("Teleported to %d, %d, %d", (int)px, (int)py, (int)pz);
}

static void run_command(const char *raw) {
    char buf[128], *av[10];
    int ac = 0;
    snprintf(buf, sizeof buf, "%s", raw);
    char *p = buf;
    if (*p == '/') p++;
    while (*p && ac < 10) {
        while (*p == ' ') p++;
        if (!*p) break;
        av[ac++] = p;
        while (*p && *p != ' ') p++;
        if (*p) *p++ = 0;
    }
    if (!ac) return;
    lower(av[0]);
    const char *c = av[0];
    if (!strcmp(c, "help")) {
        con_print("/time set day|noon|sunset|night|midnight|0-24000   /time query");
        con_print("/gamemode creative|survival  /fly  /heal  /clear  /pos  /biome  /seed");
        con_print("/tp x y z | /tp x z | /tp spawn   /setspawn   /dim overworld|nether|end");
        con_print("/give <item> [n]   /spawn <mob> [n]   /locate village   /killall   /credits");
    } else if (!strcmp(c, "time")) {
        if (ac >= 3 && !strcmp(av[1], "set")) {
            lower(av[2]);
            float t = -1.0f;
            if (!strcmp(av[2], "sunrise")) t = 0.0f; else if (!strcmp(av[2], "day")) t = 0.04f;
            else if (!strcmp(av[2], "noon")) t = 0.25f; else if (!strcmp(av[2], "sunset")) t = 0.5f;
            else if (!strcmp(av[2], "night")) t = 0.6f; else if (!strcmp(av[2], "midnight")) t = 0.75f;
            else if (av[2][0] >= '0' && av[2][0] <= '9') t = (float)(atoi(av[2]) % 24000) / 24000.0f;
            if (t < 0.0f) con_print("Usage: /time set <day|noon|sunset|night|midnight|0-24000>");
            else { g_time = t; con_print("Time set"); }
        } else {
            float hh = fmodf(g_time * 24.0f + 6.0f, 24.0f);
            con_print("Time: %02d:%02d", (int)hh, (int)((hh - floorf(hh)) * 60.0f));
        }
    } else if (!strcmp(c, "gamemode") || !strcmp(c, "gm")) {
        if (ac >= 2) lower(av[1]);
        if (ac >= 2 && (!strcmp(av[1], "creative") || !strcmp(av[1], "c") || !strcmp(av[1], "0"))) { g_mode = 0; con_print("Game mode: Creative"); }
        else if (ac >= 2 && (!strcmp(av[1], "survival") || !strcmp(av[1], "s") || !strcmp(av[1], "1"))) { g_mode = 1; g_flying = 0; con_print("Game mode: Survival"); }
        else con_print("Usage: /gamemode <creative|survival>");
    } else if (!strcmp(c, "fly")) {
        if (g_mode == 0) { g_flying = !g_flying; con_print(g_flying ? "Flying on" : "Flying off"); }
        else con_print("Flying only works in creative mode");
    } else if (!strcmp(c, "heal")) { g_health = 20; con_print("Healed"); }
    else if (!strcmp(c, "clear")) {
        memset(g_inv, 0, sizeof g_inv);
        if (g_mode == 1) memset(g_hotbar, 0, sizeof g_hotbar);
        con_print("Inventory cleared");
    } else if (!strcmp(c, "pos")) con_print("Position: %d, %d, %d", (int)px, (int)py, (int)pz);
    else if (!strcmp(c, "seed")) con_print("Seed: %d", g_seed);
    else if (!strcmp(c, "biome")) con_print("Biome: %s", cur_biome);
    else if (!strcmp(c, "setspawn")) { g_has_spawn = 1; g_sx = px; g_sy = py; g_sz = pz; con_print("Spawn point set"); }
    else if (!strcmp(c, "credits")) con_print("Coded/made by %s - %s", APP_AUTHOR, APP_STUDIO);
    else if (!strcmp(c, "killall")) { con_print("Removed %d mobs", nmobs); nmobs = 0; }
    else if (!strcmp(c, "tp")) {
        if (ac >= 2 && !strcmp(av[1], "spawn")) {
            if (g_dim != 0) goto_dim(0, 0);
            if (g_has_spawn) teleport_to(g_sx, 1, g_sy, g_sz); else teleport_to(8.5f, 0, 0.0f, 8.5f);
        } else if (ac == 4) teleport_to((float)atof(av[1]), 1, (float)atof(av[2]), (float)atof(av[3]));
        else if (ac == 3) teleport_to((float)atof(av[1]), 0, 0.0f, (float)atof(av[2]));
        else con_print("Usage: /tp <x> <y> <z>  or  /tp <x> <z>  or  /tp spawn");
    } else if (!strcmp(c, "dim") || !strcmp(c, "dimension")) {
        int t = -1;
        if (ac >= 2) {
            lower(av[1]);
            if (!strcmp(av[1], "overworld") || !strcmp(av[1], "0")) t = 0;
            else if (!strcmp(av[1], "nether") || !strcmp(av[1], "1")) t = 1;
            else if (!strcmp(av[1], "end") || !strcmp(av[1], "2")) t = 2;
        }
        if (t < 0) con_print("Usage: /dim <overworld|nether|end>");
        else if (t == g_dim) con_print("You are already there");
        else { goto_dim(t, t == 2 ? VOIDGATE : PORTAL); con_print("Welcome to the %s", t == 0 ? "Overworld" : (t == 1 ? "Nether" : "End")); }
    } else if (!strcmp(c, "locate")) {
        if (g_dim != 0) { con_print("Villages only exist in the Overworld"); return; }
        int prx_ = ifloor(px) >> 7, prz_ = ifloor(pz) >> 7, found = 0;
        float bestd = 1e30f;
        Village best, v;
        memset(&best, 0, sizeof best);
        for (int rx = prx_ - 4; rx <= prx_ + 4; rx++) for (int rz = prz_ - 4; rz <= prz_ + 4; rz++) {
            if (!village_in_region(cw, rx, rz, &v)) continue;
            float d = (v.cx - px) * (v.cx - px) + (v.cz - pz) * (v.cz - pz);
            if (d < bestd) { bestd = d; best = v; found = 1; }
        }
        if (found) con_print("Nearest village: %d, %d (%d blocks). Try /tp %d %d", best.cx, best.cz, (int)sqrtf(bestd), best.cx, best.cz);
        else con_print("No village within ~500 blocks");
    } else if (!strcmp(c, "give")) {
        if (ac < 2) { con_print("Usage: /give <item> [count]   e.g. /give diamond 5"); return; }
        int count = 1, last = ac - 1;
        if (ac > 2 && av[last][0] >= '0' && av[last][0] <= '9') { count = atoi(av[last]); last--; }
        char want[64] = "", t[64];
        for (int i = 1; i <= last; i++) { norm_name(av[i], t, sizeof t); strncat(want, t, sizeof want - strlen(want) - 1); }
        int found = -1;
        for (int id = 1; id < ITEM_MAX && found < 0; id++) {
            if (!(is_block(id) || (id >= IT_STICK && id <= IT_MEAT))) continue;
            norm_name(item_name(id), t, sizeof t);
            if (!strcmp(t, want)) found = id;
        }
        if (found < 0) { con_print("Unknown item: %s", want); return; }
        count = clampi(count, 1, 999);
        inv_give(found, count);
        if (g_mode == 0) g_hotbar[g_slot] = found;
        con_print("Gave %d x %s", count, item_name(found));
    } else if (!strcmp(c, "spawn")) {
        int t = -1;
        if (ac >= 2) { lower(av[1]); for (int i = 0; i < MOB_TYPES; i++) if (!strcmp(av[1], mob_names[i])) t = i; }
        if (t < 0) { con_print("Mobs: boar, cow, shade, cinder, villager, voidling"); return; }
        int n = ac >= 3 ? clampi(atoi(av[2]), 1, 10) : 1;
        for (int i = 0; i < n; i++) {
            float ang = yaw + (frand() - 0.5f) * 1.2f, mx = px + sinf(ang) * 3.0f, mz = pz - cosf(ang) * 3.0f;
            int sy = find_spawn_y(ifloor(mx), ifloor(mz), ifloor(py));
            add_mob(t, mx, sy >= 0 ? (float)sy : py, mz);
        }
        con_print("Spawned %d %s", n, mob_names[t]);
    } else con_print("Unknown command. Type /help");
}

/* ---- player ---- */
static int player_collides(float x, float y, float z) {
    int x0 = ifloor(x - 0.3f), x1 = ifloor(x + 0.3f), y0 = ifloor(y), y1 = ifloor(y + 1.8f), z0 = ifloor(z - 0.3f), z1 = ifloor(z + 0.3f);
    for (int xx = x0; xx <= x1; xx++) for (int yy = y0; yy <= y1; yy++) for (int zz = z0; zz <= z1; zz++)
        if (world_solid(cw, xx, yy, zz)) return 1;
    return 0;
}
static int touches_player(int bx, int by, int bz) {
    return px - 0.3f < bx + 1 && px + 0.3f > bx && py < by + 1 && py + 1.8f > by && pz - 0.3f < bz + 1 && pz + 0.3f > bz;
}
static void update_target(void) {
    float oy = py + 1.62f;
    float dx = sinf(yaw) * cosf(pitch), dy = sinf(pitch), dz = -cosf(yaw) * cosf(pitch);
    int lx = ifloor(px), ly = ifloor(oy), lz = ifloor(pz);
    hit = 0;
    for (float t = 0.0f; t < 5.0f; t += 0.02f) {
        int bx = ifloor(px + dx * t), by = ifloor(oy + dy * t), bz = ifloor(pz + dz * t);
        if (world_get(cw, bx, by, bz) != AIR) {
            hit = 1; hx = bx; hy = by; hz = bz; prx = lx; pry = ly; prz = lz;
            return;
        }
        lx = bx; ly = by; lz = bz;
    }
}

static void destroy_block(int x, int y, int z, int b) {
    world_set(cw, x, y, z, AIR);
    mark_dirty(x, z);
    swing_t = 1.0f;
    if (g_mode == 1) {
        int d = block_drop(b);
        if (d) inv_give(d, 1);
        if ((b == LEAVES || b == SPRUCE_LEAVES) && irand(10) == 0) inv_give(IT_APPLE, 1);
    }
    hit = 0;
}

static void handle_breaking(float dt, int lmb) {
    atk_cd -= dt;
    if (lmb) {
        Mob *tm = target_mob(3.6f);
        if (tm) {
            if (atk_cd <= 0.0f) { hit_mob(tm); atk_cd = 0.42f; }
            break_prog = 0.0f; break_show = 0.0f;
            return;
        }
    }
    if (lmb && hit) {
        int b = world_get(cw, hx, hy, hz);
        float hd = block_hard[b];
        if (hd >= 0.0f || (g_mode == 0 && b == LAVA)) {
            if (g_mode == 0) {
                break_cd -= dt;
                if (break_cd <= 0.0f) { destroy_block(hx, hy, hz, b); break_cd = 0.22f; }
            } else {
                if (hx != br_x || hy != br_y || hz != br_z) { break_prog = 0.0f; br_x = hx; br_y = hy; br_z = hz; }
                float factor = block_rock[b] ? best_pick() : 1.0f;
                break_prog += dt * factor / hd;
                break_show = fminf2(1.0f, break_prog);
                if (break_prog >= 1.0f) { destroy_block(hx, hy, hz, b); break_prog = 0.0f; break_show = 0.0f; }
            }
            return;
        }
    }
    break_prog = 0.0f; break_cd = 0.0f; break_show = 0.0f;
}

static void handle_use(void) {
    swing_t = 1.0f;
    Mob *tm = target_mob(3.6f);
    if (tm) {
        if (tm->type == MOB_VILLAGER) {
            if (g_mode == 1) screen = SCR_TRADE; else set_banner("Villager: Welcome, traveler!");
        }
        return;
    }
    if (hit && world_get(cw, hx, hy, hz) == BED) { do_sleep(); return; }
    int item = g_hotbar[g_slot];
    if (!item) return;
    if (is_block(item)) {
        if (hit && pry >= 0 && pry < WH && world_get(cw, prx, pry, prz) == AIR && !touches_player(prx, pry, prz) &&
            (g_mode == 0 || g_inv[item] > 0)) {
            world_set(cw, prx, pry, prz, item);
            mark_dirty(prx, prz);
            if (g_mode == 1) inv_take(item, 1);
        }
    } else if ((item == IT_APPLE || item == IT_MEAT) && g_mode == 1 && g_health < 20 && inv_take(item, 1)) {
        g_health = imin(20, g_health + (item == IT_MEAT ? 8 : 6));
    }
}

static void game_update(float dt) {
    g_time = fmodf(g_time + dt / DAY_LENGTH, 1.0f);
    float sens = 0.0022f * sens_val[set_sens];
    yaw += in.mdx * sens;
    pitch = clampf(pitch - in.mdy * sens, -1.55f, 1.55f);
    world_ensure(cw, ifloor(px) >> 4, ifloor(pz) >> 4);

    int creative = g_mode == 0, flying = creative && g_flying;
    int ix = ifloor(px), iz = ifloor(pz);
    int in_lava = world_get(cw, ix, ifloor(py + 0.3f), iz) == LAVA || world_get(cw, ix, ifloor(py + 1.2f), iz) == LAVA;
    float mx = (float)(in.key['D'] - in.key['A']), mz = (float)(in.key['W'] - in.key['S']);
    if (mx != 0.0f && mz != 0.0f) { mx *= 0.7071f; mz *= 0.7071f; }
    int jump = in.key[K_SPACE];
    float sy = sinf(yaw), cy = cosf(yaw);
    if (flying) {
        float fs = in.key[K_SHIFT] ? 16.0f : 9.0f;
        vx = (sy * mz + cy * mx) * fs;
        vz = (-cy * mz + sy * mx) * fs;
        vy = mz * sinf(pitch) * fs + (jump ? 6.0f : 0.0f);
    } else {
        float sp = in_lava ? 2.15f : (in.key[K_SHIFT] ? 5.8f : 4.3f);
        vx = (sy * mz + cy * mx) * sp;
        vz = (-cy * mz + sy * mx) * sp;
        if (in_lava) vy = jump ? 3.0f : fmaxf2(vy - 26.0f * dt * 0.3f, -2.0f);
        else {
            if (jump && on_ground) { vy = 8.2f; on_ground = 0; }
            vy = fmaxf2(vy - 26.0f * dt, -40.0f);
        }
    }
    float nx = px + vx * dt;
    if (!player_collides(nx, py, pz)) px = nx;
    float nz = pz + vz * dt;
    if (!player_collides(px, py, nz)) pz = nz;
    float ny = py + vy * dt;
    on_ground = 0;
    if (!player_collides(px, ny, pz)) py = ny;
    else { if (vy < 0.0f) on_ground = 1; vy = 0.0f; }

    if (g_dim == 2 && py < -6.0f) {
        set_banner("You fell into the void");
        if (g_mode == 1) damage(20); else respawn();
        return;
    }
    if (flying || in_lava) { was_air = 0; fall_top = py; }
    else if (on_ground) {
        if (was_air && g_mode == 1) { float d = fall_top - py; if (d > 3.5f) damage((int)(d - 3.0f)); }
        was_air = 0; fall_top = py;
    } else { was_air = 1; fall_top = fmaxf2(fall_top, py); }

    if (g_mode == 1) {
        if (in_lava) { lava_t += dt; if (lava_t >= 0.5f) { lava_t -= 0.5f; damage(2); } } else lava_t = 0.0f;
        if (g_health >= 1 && g_health <= 19) { regen_t += dt; if (regen_t >= 4.0f) { regen_t = 0.0f; g_health++; } }
    }

    int under = world_get(cw, ifloor(px), ifloor(py - 0.1f), ifloor(pz));
    if ((under == PORTAL || under == VOIDGATE) && on_ground) {
        portal_t += dt;
        if (portal_t >= 1.2f) {
            int nd = under == VOIDGATE ? (g_dim == 2 ? end_ret_dim : 2) : (g_dim == 0 ? 1 : 0);
            goto_dim(nd, under);
            return;
        }
    } else portal_t = 0.0f;

    biome_t += dt;
    if (biome_t >= 0.4f) {
        biome_t = 0.0f;
        const char *name = "Legacy Plains";
        if (g_dim == 1) name = "Ember Wastes";
        else if (g_dim == 2) name = "Void Isles";
        else {
            Village v;
            int bx = ifloor(px), bz = ifloor(pz);
            if (village_in_region(cw, bx >> 7, bz >> 7, &v) && (bx - v.cx) * (bx - v.cx) + (bz - v.cz) * (bz - v.cz) <= 576) name = "Village";
            else if (spruce_factor(cw->seed, bx, bz) > 0.5f) name = "Spruce Forest";
        }
        if (strcmp(name, cur_biome)) {
            snprintf(cur_biome, sizeof cur_biome, "%s", name);
            char b[64];
            snprintf(b, sizeof b, "Entering %s", name);
            set_banner(b);
        }
    }

    swing_t = fmaxf2(0.0f, swing_t - dt * 4.0f);
    swing_acc = in.mb[0] ? swing_acc + dt * 9.0f : 0.0f;
    if (on_ground && (mx != 0.0f || mz != 0.0f)) { walk_phase += dt * 9.0f; hand_bob = sinf(walk_phase) * 0.015f; } else hand_bob = 0.0f;
    if (banner_t > 0.0f) banner_t -= dt;

    update_target();
    update_mobs(dt);
    spawn_mobs(dt);
    handle_breaking(dt, in.mb[0]);
    if (in.mbp[1] || (in.mbp[2])) handle_use();
}

/* ---- new game / save / load ---- */
static void game_reset_world(int seed) {
    for (int d = 0; d < 3; d++) { release_world(&worlds[d]); free_edits(&worlds[d]); world_init(&worlds[d], d, seed); }
    cw = &worlds[0];
    g_seed = seed; g_dim = 0; nmobs = 0;
}

static void game_new(int mode, int seed) {
    game_reset_world(seed);
    memset(g_inv, 0, sizeof g_inv);
    memset(g_hotbar, 0, sizeof g_hotbar);
    g_mode = mode; g_health = 20; g_flying = 0; g_slot = 0; g_time = 0.03f; g_has_spawn = 0;
    if (mode == 0) {
        static const int d[9] = {GRASS, DIRT, STONE, PLANKS, LOG, BED, LUMEN, PORTAL, VOIDGATE};
        memcpy(g_hotbar, d, sizeof d);
    }
    for (int dx = -1; dx <= 1; dx++) for (int dz = -1; dz <= 1; dz++) world_ensure(cw, dx, dz);
    px = 8.5f; pz = 8.5f; py = world_surface_y(cw, 8, 8) + 1.0f;
    yaw = 0.0f; pitch = 0.0f; vx = vy = vz = 0.0f; fall_top = py; was_air = 0; on_ground = 0;
    cur_biome[0] = 0; banner[0] = 0; con_n = 0; con_in[0] = 0; con_len = 0; break_prog = 0.0f;
    in_game = 1;
}

static int save_game(void) {
    if (!in_game) return 0;
    FILE *f = fopen(SAVE_FILE, "wb");
    if (!f) return 0;
    int ver = 1;
    float fl[8] = {px, py, pz, yaw, pitch, g_time, g_sx, g_sy};
    fwrite(&ver, sizeof ver, 1, f);
    fwrite(&g_seed, sizeof g_seed, 1, f); fwrite(&g_mode, sizeof g_mode, 1, f); fwrite(&g_dim, sizeof g_dim, 1, f);
    fwrite(&g_health, sizeof g_health, 1, f); fwrite(&g_has_spawn, sizeof g_has_spawn, 1, f);
    fwrite(fl, sizeof fl, 1, f); fwrite(&g_sz, sizeof g_sz, 1, f);
    fwrite(g_hotbar, sizeof g_hotbar, 1, f); fwrite(g_inv, sizeof g_inv, 1, f);
    for (int d = 0; d < 3; d++) {
        int nce = 0;
        for (int b = 0; b < CE_HASH; b++) for (CE *e = worlds[d].ce[b]; e; e = e->next) nce++;
        fwrite(&nce, sizeof nce, 1, f);
        for (int b = 0; b < CE_HASH; b++) for (CE *e = worlds[d].ce[b]; e; e = e->next) {
            fwrite(&e->key, sizeof e->key, 1, f); fwrite(&e->n, sizeof e->n, 1, f);
            fwrite(e->idx, sizeof(int), (size_t)e->n, f); fwrite(e->b, 1, (size_t)e->n, f);
        }
    }
    fclose(f);
    return 1;
}

static int load_game(void) {
    FILE *f = fopen(SAVE_FILE, "rb");
    if (!f) return 0;
    int ver = 0, seed = 0, mode = 0, dim = 0, hp = 20, hs = 0;
    float fl[8], sz = 0.0f;
    int ok = fread(&ver, sizeof ver, 1, f) == 1 && ver == 1 && fread(&seed, sizeof seed, 1, f) == 1 &&
             fread(&mode, sizeof mode, 1, f) == 1 && fread(&dim, sizeof dim, 1, f) == 1 &&
             fread(&hp, sizeof hp, 1, f) == 1 && fread(&hs, sizeof hs, 1, f) == 1 && fread(fl, sizeof fl, 1, f) == 1 &&
             fread(&sz, sizeof sz, 1, f) == 1;
    if (!ok) { fclose(f); return 0; }
    game_reset_world(seed);
    g_mode = mode; g_health = hp; g_has_spawn = hs; g_sz = sz;
    px = fl[0]; py = fl[1]; pz = fl[2]; yaw = fl[3]; pitch = fl[4]; g_time = fl[5]; g_sx = fl[6]; g_sy = fl[7];
    if (fread(g_hotbar, sizeof g_hotbar, 1, f) != 1 || fread(g_inv, sizeof g_inv, 1, f) != 1) { fclose(f); return 0; }
    for (int d = 0; d < 3; d++) {
        int nce = 0;
        if (fread(&nce, sizeof nce, 1, f) != 1) break;
        for (int i = 0; i < nce; i++) {
            long long key; int n;
            if (fread(&key, sizeof key, 1, f) != 1 || fread(&n, sizeof n, 1, f) != 1 || n < 0 || n > 16 * WH * 16) { fclose(f); return 0; }
            CE *e = ce_find(&worlds[d], key, 1);
            e->idx = (int *)xrealloc(e->idx, sizeof(int) * (size_t)(n + 1));
            e->b = (unsigned char *)xrealloc(e->b, (size_t)(n + 1));
            e->cap = n + 1; e->n = n;
            if (fread(e->idx, sizeof(int), (size_t)n, f) != (size_t)n || fread(e->b, 1, (size_t)n, f) != (size_t)n) { fclose(f); return 0; }
        }
    }
    fclose(f);
    g_dim = dim; cw = &worlds[dim];
    for (int dx = -1; dx <= 1; dx++) for (int dz = -1; dz <= 1; dz++) world_ensure(cw, (ifloor(px) >> 4) + dx, (ifloor(pz) >> 4) + dz);
    g_flying = 0; g_slot = 0; vx = vy = vz = 0.0f; fall_top = py; was_air = 0; on_ground = 0; nmobs = 0;
    cur_biome[0] = 0; banner[0] = 0; con_n = 0; break_prog = 0.0f;
    in_game = 1;
    return 1;
}

/* ------------------------------------------------------------------ text (Win32 bitmap fonts) */

static int g_quit;

#ifdef VOX_HEADLESS
static float text_width(int font, const char *s) { return (float)strlen(s) * (font == 2 ? 36.0f : (font == 1 ? 11.0f : 8.0f)); }
static void text_draw(int font, float x, float y, const char *s) { (void)font; (void)x; (void)y; (void)s; }
#else
static HWND g_hwnd;
static HDC g_hdc;
static HGLRC g_rc;
static unsigned font_base[3];
static HFONT font_obj[3];
static void text_init(void) {
    static const int sizes[3] = {16, 22, 72};
    static const int weights[3] = {FW_NORMAL, FW_BOLD, FW_BOLD};
    for (int i = 0; i < 3; i++) {
        font_obj[i] = CreateFontA(-sizes[i], 0, 0, 0, weights[i], FALSE, FALSE, FALSE, ANSI_CHARSET, OUT_TT_PRECIS,
                                  CLIP_DEFAULT_PRECIS, ANTIALIASED_QUALITY, DEFAULT_PITCH | FF_DONTCARE, "Consolas");
        SelectObject(g_hdc, font_obj[i]);
        font_base[i] = glGenLists(96);
        wglUseFontBitmapsA(g_hdc, 32, 96, font_base[i]);
    }
}
static float text_width(int font, const char *s) {
    SIZE sz;
    SelectObject(g_hdc, font_obj[font]);
    GetTextExtentPoint32A(g_hdc, s, (int)strlen(s), &sz);
    return (float)sz.cx;
}
static void text_draw(int font, float x, float y, const char *s) {
    glRasterPos2f(x, y);
    glListBase(font_base[font] - 32);
    glCallLists((GLsizei)strlen(s), GL_UNSIGNED_BYTE, s);
}
#endif

/* ------------------------------------------------------------------ rendering helpers */

static GLuint atlas_tex;

static void gl_init(void) {
    glGenTextures(1, &atlas_tex);
    glBindTexture(GL_TEXTURE_2D, atlas_tex);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, ATLAS_SIZE, ATLAS_SIZE, 0, GL_RGBA, GL_UNSIGNED_BYTE, atlas_px);
    glEnable(GL_DEPTH_TEST);
    glDepthFunc(GL_LEQUAL);
}

static void begin_2d(void) {
    glViewport(0, 0, in.w, in.h);
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    glOrtho(0, in.w, in.h, 0, -1, 1);
    glMatrixMode(GL_MODELVIEW);
    glLoadIdentity();
    glDisable(GL_DEPTH_TEST); glDisable(GL_LIGHTING); glDisable(GL_FOG); glDisable(GL_TEXTURE_2D);
    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
}

static void rect(float x, float y, float w, float h, float r, float g, float b, float a) {
    glColor4f(r, g, b, a);
    glBegin(GL_QUADS);
    glVertex2f(x, y); glVertex2f(x + w, y); glVertex2f(x + w, y + h); glVertex2f(x, y + h);
    glEnd();
}
static void frame_rect(float x, float y, float w, float h, float t, float r, float g, float b, float a) {
    rect(x, y, w, t, r, g, b, a); rect(x, y + h - t, w, t, r, g, b, a);
    rect(x, y, t, h, r, g, b, a); rect(x + w - t, y, t, h, r, g, b, a);
}
static void text(int font, float x, float y, const char *s, float r, float g, float b) {
    glColor3f(r, g, b);
    text_draw(font, x, y, s);
}
static void text_shadow(int font, float x, float y, const char *s, float r, float g, float b) {
    text(font, x + 2, y + 2, s, 0, 0, 0);
    text(font, x, y, s, r, g, b);
}
static void text_center(int font, float cx, float y, const char *s, float r, float g, float b) {
    text(font, cx - text_width(font, s) / 2.0f, y, s, r, g, b);
}

static void tile_icon(float x, float y, float size, int tile) {
    float inv = 1.0f / ATLAS_TILES, u = (float)(tile % ATLAS_TILES) * inv, v = (float)(tile / ATLAS_TILES) * inv;
    glEnable(GL_TEXTURE_2D);
    glBindTexture(GL_TEXTURE_2D, atlas_tex);
    glColor4f(1, 1, 1, 1);
    glBegin(GL_QUADS);
    glTexCoord2f(u, v); glVertex2f(x, y);
    glTexCoord2f(u + inv, v); glVertex2f(x + size, y);
    glTexCoord2f(u + inv, v + inv); glVertex2f(x + size, y + size);
    glTexCoord2f(u, v + inv); glVertex2f(x, y + size);
    glEnd();
    glDisable(GL_TEXTURE_2D);
}

static int ui_click;
static int hover(float x, float y, float w, float h) {
    return in.mx >= x && in.mx <= x + w && in.my >= y && in.my <= y + h;
}
static int button(float x, float y, float w, float h, const char *label, float r, float g, float b) {
    int hv = hover(x, y, w, h);
    float k = hv ? 1.3f : 1.0f;
    rect(x, y, w, h, fminf2(r * k, 1), fminf2(g * k, 1), fminf2(b * k, 1), 0.93f);
    frame_rect(x, y, w, h, 2, 1, 1, 1, 0.7f);
    text_center(0, x + w / 2, y + h / 2 + 5, label, 1, 1, 1);
    if (hv && ui_click) { ui_click = 0; return 1; }
    return 0;
}

/* ------------------------------------------------------------------ 3D scene */

static void compute_sky(float sky[3], float tint[3], float *bn_out, float *sun_out) {
    float sun = sinf(g_time * TAU_F), bright = brightness_of(g_time), bn = (bright - 0.14f) / 0.86f;
    *bn_out = bn; *sun_out = sun;
    if (g_dim == 0) {
        sky[0] = 0.015f + 0.515f * bn; sky[1] = 0.02f + 0.79f * bn; sky[2] = 0.07f + 0.85f * bn;
        float sf = fmaxf2(0.0f, 1.0f - fabsf(sun) / 0.3f) * 0.4f;
        sky[0] = sky[0] * (1 - sf) + 1.0f * sf; sky[1] = sky[1] * (1 - sf) + 0.55f * sf; sky[2] = sky[2] * (1 - sf) + 0.3f * sf;
        float light = 0.22f + 0.78f * bn;
        tint[0] = tint[1] = tint[2] = light;
    } else if (g_dim == 1) {
        sky[0] = 0.28f; sky[1] = 0.06f; sky[2] = 0.05f;
        tint[0] = 1.0f; tint[1] = 0.74f; tint[2] = 0.68f;
    } else {
        sky[0] = 0.03f; sky[1] = 0.015f; sky[2] = 0.07f;
        tint[0] = 0.85f; tint[1] = 0.8f; tint[2] = 1.0f;
    }
}

/* axis-aligned box centred at (cx,cy,cz); flat = use one colour tile for every face */
static void draw_box(float cx, float cy, float cz, float hx, float hy, float hz, int top, int side, int bottom, int flat) {
    float inv = 1.0f / ATLAS_TILES, eps = 0.0015f, span = inv - 2.0f * eps;
    glBegin(GL_QUADS);
    for (int f = 0; f < 6; f++) {
        int tile = f == 0 ? top : (f == 1 ? bottom : side);
        float tu = (float)(tile % ATLAS_TILES) * inv, tv = (float)(tile / ATLAS_TILES) * inv;
        glColor3f(FSH[f], FSH[f], FSH[f]);
        for (int k = 0; k < 4; k++) {
            float u = flat ? tu + inv * 0.5f : tu + eps + FUV[f][k * 2] * span;
            float v = flat ? tv + inv * 0.5f : tv + eps + FUV[f][k * 2 + 1] * span;
            glTexCoord2f(u, v);
            glVertex3f(cx + (FC[f][k * 3] * 2 - 1) * hx, cy + (FC[f][k * 3 + 1] * 2 - 1) * hy, cz + (FC[f][k * 3 + 2] * 2 - 1) * hz);
        }
    }
    glEnd();
}

/* a box that swings around its top (hip/shoulder) edge */
static void part(int flash, float cx, float cy, float cz, float hx, float hy, float hz, int tile, float swing, int glow) {
    int t = flash ? 63 : tile;
    glPushMatrix();
    if (swing != 0.0f) {
        glTranslatef(cx, cy + hy, cz);
        glRotatef(swing * 57.29578f, 1, 0, 0);
        glTranslatef(-cx, -(cy + hy), -cz);
    }
    if (glow) glDisable(GL_LIGHTING);
    draw_box(cx, cy, cz, hx, hy, hz, t, t, t, 1);
    if (glow) glEnable(GL_LIGHTING);
    glPopMatrix();
}

static void humanoid(int fl, float sw, int body, int legs, int arms, int head, int eyes) {
    part(fl, -0.15f, 0.35f, 0, 0.14f, 0.35f, 0.14f, legs, sw, 0);
    part(fl, 0.15f, 0.35f, 0, 0.14f, 0.35f, 0.14f, legs, -sw, 0);
    part(fl, 0, 1.05f, 0, 0.3f, 0.35f, 0.17f, body, 0, 0);
    part(fl, -0.44f, 1.05f, 0, 0.11f, 0.35f, 0.11f, arms, -sw, 0);
    part(fl, 0.44f, 1.05f, 0, 0.11f, 0.35f, 0.11f, arms, sw, 0);
    part(fl, 0, 1.65f, 0, 0.25f, 0.25f, 0.25f, head, 0, 0);
    part(fl, -0.12f, 1.68f, 0.255f, 0.06f, 0.05f, 0.012f, eyes, 0, 1);
    part(fl, 0.12f, 1.68f, 0.255f, 0.06f, 0.05f, 0.012f, eyes, 0, 1);
}
static void legs4(int fl, float sw, float hw, float hh, int tile, float lx, float lz) {
    part(fl, -lx, hh, lz, hw, hh, hw, tile, sw, 0);
    part(fl, lx, hh, lz, hw, hh, hw, tile, -sw, 0);
    part(fl, -lx, hh, -lz, hw, hh, hw, tile, -sw, 0);
    part(fl, lx, hh, -lz, hw, hh, hw, tile, sw, 0);
}

/* flat colour tiles: 48 pink, 49 dark pink, 50 brown, 51 white, 52 black, 53 skin, 54 robe, 55 purple, 56 magenta,
   57 orange, 58 dark red, 59 yellow, 60 dark violet, 61 violet, 62 green, 63 red (hurt flash) */
static void draw_mob(const Mob *m) {
    int fl = m->hurt > 0.0f;
    float sw = sinf(m->phase) * ((m->walking || m->type == MOB_SHADE) ? 0.7f : 0.05f);
    glPushMatrix();
    glTranslatef(m->x, m->y, m->z);
    glRotatef(m->yaw * 57.29578f, 0, 1, 0);
    switch (m->type) {
        case MOB_BOAR:
            part(fl, 0, 0.55f, 0, 0.3f, 0.25f, 0.5f, 48, 0, 0);
            part(fl, 0, 0.7f, 0.58f, 0.22f, 0.2f, 0.2f, 48, 0, 0);
            part(fl, 0, 0.64f, 0.8f, 0.1f, 0.08f, 0.05f, 49, 0, 0);
            part(fl, -0.12f, 0.78f, 0.79f, 0.04f, 0.04f, 0.012f, 52, 0, 0);
            part(fl, 0.12f, 0.78f, 0.79f, 0.04f, 0.04f, 0.012f, 52, 0, 0);
            legs4(fl, sw, 0.1f, 0.2f, 49, 0.2f, 0.33f);
            break;
        case MOB_COW:
            part(fl, 0, 0.95f, 0, 0.35f, 0.35f, 0.6f, 50, 0, 0);
            part(fl, 0.36f, 1.0f, 0.1f, 0.02f, 0.18f, 0.22f, 51, 0, 0);
            part(fl, -0.36f, 0.9f, -0.2f, 0.02f, 0.16f, 0.2f, 51, 0, 0);
            part(fl, 0, 1.1f, 0.78f, 0.24f, 0.24f, 0.2f, 50, 0, 0);
            part(fl, 0, 1.0f, 0.97f, 0.14f, 0.1f, 0.04f, 51, 0, 0);
            part(fl, -0.13f, 1.18f, 0.985f, 0.04f, 0.04f, 0.012f, 52, 0, 0);
            part(fl, 0.13f, 1.18f, 0.985f, 0.04f, 0.04f, 0.012f, 52, 0, 0);
            legs4(fl, sw, 0.12f, 0.3f, 50, 0.22f, 0.4f);
            break;
        case MOB_SHADE: humanoid(fl, sw, 55, 60, 55, 55, 56); break;
        case MOB_CINDER: humanoid(fl, sw, 57, 58, 58, 57, 59); break;
        case MOB_VOIDLING: glScalef(1.25f, 1.25f, 1.25f); humanoid(fl, sw, 60, 60, 60, 60, 61); break;
        default:
            part(fl, -0.15f, 0.3f, 0, 0.14f, 0.3f, 0.14f, 54, sw, 0);
            part(fl, 0.15f, 0.3f, 0, 0.14f, 0.3f, 0.14f, 54, -sw, 0);
            part(fl, 0, 0.9f, 0, 0.32f, 0.6f, 0.2f, 54, 0, 0);
            part(fl, -0.44f, 1.0f, 0, 0.1f, 0.35f, 0.1f, 54, -sw, 0);
            part(fl, 0.44f, 1.0f, 0, 0.1f, 0.35f, 0.1f, 54, sw, 0);
            part(fl, 0, 1.65f, 0, 0.25f, 0.25f, 0.25f, 53, 0, 0);
            part(fl, 0, 1.58f, 0.29f, 0.05f, 0.1f, 0.05f, 49, 0, 0);
            part(fl, -0.12f, 1.7f, 0.255f, 0.05f, 0.04f, 0.012f, 62, 0, 0);
            part(fl, 0.12f, 1.7f, 0.255f, 0.05f, 0.04f, 0.012f, 62, 0, 0);
            part(fl, 0, 1.92f, 0, 0.27f, 0.05f, 0.27f, 50, 0, 0);
            break;
    }
    glPopMatrix();
}

static void render_hand(void) {
    if (set_hand == 2) return;
    float side = set_hand == 1 ? -1.0f : 1.0f;
    float sw = swing_t > 0.0f ? sinf((1.0f - swing_t) * PI_F) : 0.0f;
    float cont = in.mb[0] ? fabsf(sinf(swing_acc)) * 0.8f : 0.0f;
    float swing = fmaxf2(sw, cont);
    float a = 0.5f + swing * 0.9f, b = side * (0.35f - swing * 0.25f);
    glClear(GL_DEPTH_BUFFER_BIT);
    glMatrixMode(GL_MODELVIEW);
    glLoadIdentity();
    glTranslatef(side * 0.42f, -0.44f + hand_bob + swing * 0.05f, -0.55f - swing * 0.12f);
    glRotatef(b * 57.29578f, 0, 1, 0);
    glRotatef(a * 57.29578f, 1, 0, 0);
    draw_box(0, 0, -0.30f, 0.085f, 0.085f, 0.30f, 53, 53, 53, 1);
    draw_box(0, 0, -0.08f, 0.095f, 0.095f, 0.10f, 54, 54, 54, 1);
    int held = g_hotbar[g_slot];
    if (held > 0) {
        if (is_block(held)) draw_box(0, 0.15f, -0.66f, 0.105f, 0.105f, 0.105f, tile_top[held], tile_side[held], tile_bottom[held], 0);
        else {
            int t = item_tile(held);
            glEnable(GL_ALPHA_TEST);
            glAlphaFunc(GL_GREATER, 0.5f);
            draw_box(0, 0.2f, -0.62f, 0.16f, 0.16f, 0.003f, t, t, t, 0);
            glDisable(GL_ALPHA_TEST);
        }
    }
}

static void render_world(void) {
    float sky[3], tint[3], bn, sun;
    compute_sky(sky, tint, &bn, &sun);
    float aspect = (float)in.w / (float)(in.h > 0 ? in.h : 1);
    glViewport(0, 0, in.w, in.h);
    glClearColor(sky[0], sky[1], sky[2], 1.0f);
    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
    glMatrixMode(GL_PROJECTION);
    glLoadIdentity();
    float top = 0.1f * tanf((float)set_fov * PI_F / 360.0f);
    glFrustum(-top * aspect, top * aspect, -top, top, 0.1, 400.0);
    glMatrixMode(GL_MODELVIEW);
    glLoadIdentity();
    glRotatef(-pitch * 57.29578f, 1, 0, 0);
    glRotatef(yaw * 57.29578f, 0, 1, 0);

    /* sky: stars, sun and moon are drawn around the camera */
    glDisable(GL_DEPTH_TEST); glDisable(GL_TEXTURE_2D); glDisable(GL_LIGHTING); glDisable(GL_FOG);
    float star_a = g_dim == 2 ? 1.0f : (g_dim == 0 ? clampf((0.5f - brightness_of(g_time)) / 0.3f, 0.0f, 1.0f) : 0.0f);
    if (star_a > 0.02f) {
        glColor3f(star_a, star_a, star_a);
        glPointSize(2.0f);
        glBegin(GL_POINTS);
        for (int i = 0; i < 220; i++) {
            float z = ((hash2(i, 7, 99) & 0xFFFF) / 65535.0f) * 2.0f - 1.0f, phi = ((hash2(i, 8, 99) & 0xFFFF) / 65535.0f) * TAU_F;
            float s = sqrtf(1.0f - z * z);
            glVertex3f(s * cosf(phi) * 150.0f, z * 150.0f, s * sinf(phi) * 150.0f);
        }
        glEnd();
    }
    if (g_dim == 0) {
        float a = g_time * TAU_F;
        for (int k = 0; k < 2; k++) {
            float dx = (k ? -1 : 1) * cosf(a), dy = (k ? -1 : 1) * sinf(a), dz = (k ? -0.25f : 0.25f);
            float len = sqrtf(dx * dx + dy * dy + dz * dz);
            dx /= len; dy /= len; dz /= len;
            if (dy < -0.25f) continue;
            float ux = 0, uy = 1, uz = 0;
            if (fabsf(dy) > 0.95f) { ux = 1; uy = 0; }
            float rx = dy * uz - dz * uy, ry = dz * ux - dx * uz, rz = dx * uy - dy * ux;
            float rl = sqrtf(rx * rx + ry * ry + rz * rz);
            rx /= rl; ry /= rl; rz /= rl;
            float u2x = ry * dz - rz * dy, u2y = rz * dx - rx * dz, u2z = rx * dy - ry * dx;
            float size = k ? 9.0f : 12.0f;
            if (k) glColor3f(0.86f, 0.89f, 0.96f); else glColor3f(1.0f, 0.93f, 0.55f);
            glBegin(GL_QUADS);
            for (int c = 0; c < 4; c++) {
                float sr = (c == 0 || c == 3) ? -1.0f : 1.0f, su = (c < 2) ? -1.0f : 1.0f;
                glVertex3f(dx * 120 + (rx * sr + u2x * su) * size, dy * 120 + (ry * sr + u2y * su) * size, dz * 120 + (rz * sr + u2z * su) * size);
            }
            glEnd();
        }
    }

    float ex = px, ey = py + 1.62f, ez = pz;
    glTranslatef(-ex, -ey, -ez);
    glEnable(GL_DEPTH_TEST);
    glEnable(GL_TEXTURE_2D);
    glBindTexture(GL_TEXTURE_2D, atlas_tex);
    float fogc[4] = {sky[0], sky[1], sky[2], 1.0f};
    glEnable(GL_FOG);
    glFogi(GL_FOG_MODE, GL_LINEAR);
    glFogf(GL_FOG_START, set_dist * 16.0f * 0.5f);
    glFogf(GL_FOG_END, set_dist * 16.0f);
    glFogfv(GL_FOG_COLOR, fogc);
    float amb[4] = {tint[0], tint[1], tint[2], 1.0f};
    glLightModelfv(GL_LIGHT_MODEL_AMBIENT, amb);
    glEnable(GL_COLOR_MATERIAL);
    glColorMaterial(GL_FRONT_AND_BACK, GL_AMBIENT_AND_DIFFUSE);

    float fx = sinf(yaw) * cosf(pitch), fy = sinf(pitch), fz = -cosf(yaw) * cosf(pitch);
    for (int pass = 0; pass < 2; pass++) {
        if (pass == 0) glEnable(GL_LIGHTING); else glDisable(GL_LIGHTING);
        for (int b = 0; b < CH_HASH; b++) {
            for (Chunk *c = cw->buckets[b]; c; c = c->next) {
                unsigned int l = pass ? c->list_glow : c->list_main;
                if (!l) continue;
                float cx = c->cx * 16 + 8 - ex, cy = 32 - ey, cz = c->cz * 16 + 8 - ez;
                if (cx * fx + cy * fy + cz * fz < -26.0f) continue;
                if (cx * cx + cz * cz > (set_dist + 1) * 16.0f * (set_dist + 1) * 16.0f) continue;
                glCallList(l);
            }
        }
    }

    glEnable(GL_LIGHTING);
    for (int i = 0; i < nmobs; i++) draw_mob(&mobs[i]);

    if (hit) { /* outline of the targeted block */
        glDisable(GL_LIGHTING); glDisable(GL_TEXTURE_2D); glDisable(GL_FOG);
        glColor3f(0, 0, 0);
        glLineWidth(2.0f);
        float lo = -0.003f, hi = 1.003f, x = (float)hx, y = (float)hy, z = (float)hz;
        static const int ed[24] = {0, 1, 1, 2, 2, 3, 3, 0, 4, 5, 5, 6, 6, 7, 7, 4, 0, 4, 1, 5, 2, 6, 3, 7};
        glBegin(GL_LINES);
        for (int i = 0; i < 24; i++) {
            int c = ed[i];
            float cxp = (c == 1 || c == 2 || c == 5 || c == 6) ? hi : lo, cyp = c >= 4 ? hi : lo, czp = (c == 2 || c == 3 || c == 6 || c == 7) ? hi : lo;
            glVertex3f(x + cxp, y + cyp, z + czp);
        }
        glEnd();
        glEnable(GL_TEXTURE_2D);
    }
    glDisable(GL_FOG);
    glEnable(GL_LIGHTING);
    render_hand();
}

