static void draw_hud(void) {
    begin_2d();
    float cxm = in.w / 2.0f, cym = in.h / 2.0f;
    rect(cxm - 9, cym - 1, 18, 2, 1, 1, 1, 0.9f);
    rect(cxm - 1, cym - 9, 2, 18, 1, 1, 1, 0.9f);
    if (break_show > 0.0f) {
        rect(cxm - 35, cym + 24, 70, 6, 0, 0, 0, 0.6f);
        rect(cxm - 35, cym + 24, 70 * break_show, 6, 1, 1, 1, 0.9f);
    }
    char buf[160];
    const char *dn = g_dim == 0 ? "Overworld" : (g_dim == 1 ? "Nether" : "The End");
    float hh = fmodf(g_time * 24.0f + 6.0f, 24.0f);
    snprintf(buf, sizeof buf, "%s - %s", dn, cur_biome);
    text_shadow(0, 12, 22, buf, 1, 1, 1);
    snprintf(buf, sizeof buf, "%s   %02d:%02d   %d FPS", g_mode == 0 ? "Creative" : "Survival", (int)hh, (int)((hh - floorf(hh)) * 60.0f), (int)fps_now);
    text_shadow(0, 12, 42, buf, 1, 1, 1);
    snprintf(buf, sizeof buf, "%d, %d, %d", ifloor(px), ifloor(py), ifloor(pz));
    text_shadow(0, 12, 62, buf, 0.9f, 0.9f, 0.9f);
    if (g_mode == 1) {
        for (int i = 0; i < 10; i++) {
            int full = g_health >= (i + 1) * 2, half = g_health == i * 2 + 1;
            rect(cxm - 175 + i * 18, in.h - 100.0f, 15, 15, 0.2f, 0.0f, 0.0f, 0.7f);
            if (full) rect(cxm - 175 + i * 18, in.h - 100.0f, 15, 15, 0.95f, 0.2f, 0.25f, 1.0f);
            else if (half) rect(cxm - 175 + i * 18, in.h - 100.0f, 8, 15, 0.95f, 0.2f, 0.25f, 1.0f);
        }
    }
    if (banner_t > 0.0f) text_center(1, cxm, 110, banner, 1, 1, 1);
    for (int i = 0; i < 9; i++) {
        float x = cxm - 9 * 27.0f + i * 54.0f, y = in.h - 70.0f;
        rect(x, y, 50, 50, 0, 0, 0, 0.55f);
        frame_rect(x, y, 50, 50, i == g_slot ? 3.0f : 1.0f, 1, 1, 1, i == g_slot ? 1.0f : 0.4f);
        int id = g_hotbar[i];
        if (id) {
            tile_icon(x + 6, y + 6, 38, item_tile(id));
            if (g_mode == 1) {
                snprintf(buf, sizeof buf, "%d", g_inv[id]);
                text_shadow(0, x + 30, y + 46, buf, 1, 1, 1);
                if (g_inv[id] == 0) rect(x, y, 50, 50, 0, 0, 0, 0.55f);
            }
        }
    }
}

