static const char *splashes[] = {"Endless worlds!", "Now with villagers!", "Sleep through the night!", "Beware the dark!", "Floating islands!", "Coded by Igurs0023!", "Try /help!", "Mind the void!"};

static void menu_background(float t) {
    begin_2d();
    float w = (float)in.w, h = (float)in.h;
    glBegin(GL_QUADS);
    glColor3f(0.02f, 0.03f, 0.10f); glVertex2f(0, 0); glVertex2f(w, 0);
    glColor3f(0.17f, 0.09f, 0.32f); glVertex2f(w, h * 0.6f); glVertex2f(0, h * 0.6f);
    glColor3f(0.17f, 0.09f, 0.32f); glVertex2f(0, h * 0.6f); glVertex2f(w, h * 0.6f);
    glColor3f(0.55f, 0.23f, 0.29f); glVertex2f(w, h); glVertex2f(0, h);
    glEnd();
    for (int i = 0; i < 90; i++) {
        float x = (hash2(i, 1, 5) & 0xFFFF) / 65535.0f * w, y = (hash2(i, 2, 5) & 0xFFFF) / 65535.0f * h * 0.65f;
        float a = 0.3f + 0.7f * (0.5f + 0.5f * sinf(t * 1.5f + (float)i));
        rect(x, y, 2, 2, 1, 1, 1, a);
    }
    rect(w * 0.88f - 22, h * 0.16f - 22, 44, 44, 0.93f, 0.95f, 1.0f, 1.0f);
    static const float cols[8][3] = {{0.37f, 0.62f, 0.21f}, {0.53f, 0.38f, 0.26f}, {0.49f, 0.49f, 0.49f}, {0.86f, 0.81f, 0.56f}, {0.9f, 0.35f, 0.08f}, {0.59f, 0.31f, 0.9f}, {0.31f, 0.87f, 0.93f}, {0.7f, 0.23f, 0.23f}};
    for (int i = 0; i < 8; i++) {
        float s = (10.0f + (hash2(i, 3, 5) & 15)) * (h / 600.0f + 0.5f);
        float x = fmodf((float)i * w / 8.0f + t * (6.0f + i), w + 80.0f) - 40.0f;
        float y = h * (0.2f + 0.5f * ((hash2(i, 4, 5) & 0xFF) / 255.0f)) + sinf(t * 0.8f + (float)i) * 14.0f;
        float k = 0.866f * s;
        glBegin(GL_QUADS);
        glColor3f(cols[i][0], cols[i][1], cols[i][2]);
        glVertex2f(x, y - s); glVertex2f(x + k, y - s * 0.5f); glVertex2f(x, y); glVertex2f(x - k, y - s * 0.5f);
        glColor3f(cols[i][0] * 0.72f, cols[i][1] * 0.72f, cols[i][2] * 0.72f);
        glVertex2f(x - k, y - s * 0.5f); glVertex2f(x, y); glVertex2f(x, y + s); glVertex2f(x - k, y + s * 0.5f);
        glColor3f(cols[i][0] * 0.5f, cols[i][1] * 0.5f, cols[i][2] * 0.5f);
        glVertex2f(x, y); glVertex2f(x + k, y - s * 0.5f); glVertex2f(x + k, y + s * 0.5f); glVertex2f(x, y + s);
        glEnd();
    }
    glColor3f(0.05f, 0.04f, 0.12f);
    glBegin(GL_QUADS);
    for (float x = 0; x < w; x += 16.0f) {
        float y0 = h * 0.86f + sinf(x * 0.012f + 1.0f) * h * 0.03f + cosf(x * 0.031f) * h * 0.015f;
        glVertex2f(x, y0); glVertex2f(x + 16, y0); glVertex2f(x + 16, h); glVertex2f(x, h);
    }
    glEnd();
}

static void start_new(int mode) {
    game_new(mode, (int)(time(NULL) & 0xFFFFFF) + 1);
    screen = SCR_GAME;
}
static void start_continue(void) {
    if (load_game()) screen = SCR_GAME;
}

static int option_row(float y, const char *label, const char **opts, int n, int sel, int disabled_from) {
    float w = (float)in.w, x0 = w / 2 - 300;
    text(0, x0, y + 22, label, 1.0f, 0.55f, 0.67f);
    int clicked = -1;
    float bw = 112.0f;
    for (int i = 0; i < n; i++) {
        int dis = disabled_from >= 0 && i >= disabled_from;
        if (button(x0 + 190 + i * (bw + 6), y, bw, 32, opts[i], i == sel ? 0.24f : 0.2f, i == sel ? 0.35f : 0.21f, i == sel ? 1.0f : 0.31f) && !dis) clicked = i;
        else if (dis && hover(x0 + 190 + i * (bw + 6), y, bw, 32) && in.mbp[0]) set_banner("Vulkan needs a native renderer - not in this edition");
    }
    return clicked;
}

static void save_settings(void) {
    FILE *f = fopen("voxcraft_settings.cfg", "w");
    if (!f) return;
    fprintf(f, "%d %d %d %d %d\n", set_dist, set_fov, set_sens, set_hand, set_vsync);
    fclose(f);
}
static void load_settings(void) {
    FILE *f = fopen("voxcraft_settings.cfg", "r");
    if (!f) return;
    int a, b, c, d, e;
    if (fscanf(f, "%d %d %d %d %d", &a, &b, &c, &d, &e) == 5) {
        set_dist = clampi(a, 3, 10); set_fov = clampi(b, 50, 110); set_sens = clampi(c, 0, 2); set_hand = clampi(d, 0, 2); set_vsync = clampi(e, 0, 1);
    }
    fclose(f);
}

